import data from './affix-tiers.json';
import type {AffixRow,Item} from './model';

/** Generated by scripts/affix-tiers.mjs from Path of Building Community (PoE2); see its header for the ranking. */
type Mod=[id:string,type:'P'|'S',affix:string,lines:string[]];
const table=data as unknown as {pob:string;tables:string[];tableStarts:number[];mods:Mod[];series:number[][];untiered:number[];classes:number[][];catalyst:number[];bases:Record<string,number>};
export const TIER_DATA_VERSION=table.pob;

const byId=new Map(table.mods.map((m,i)=>[m[0],i]));
const untiered=new Set(table.untiered),catalyst=new Set(table.catalyst);
const inSeries=new Set(table.series.flat());
const tableOf=(mod:number)=>table.tableStarts.reduce((found,start,n)=>start>=0&&mod>=start?n:found,0);
const baseNames=Object.keys(table.bases).sort((a,b)=>b.length-a.length);

interface BaseClass {tiers:Map<number,{tier?:number;tiers?:number}>;pool:number[];tables:Set<number>;scaled:boolean}
const classes=new Map<number,BaseClass>();
function baseClass(item:Item):BaseClass|undefined{
 const base=item.base||'';
 // A magic item from PoB names its base inside the affix words: "Gleaming Soaring Spear of Celebration".
 const name=Object.hasOwn(table.bases,base)?base:item.rarity==='magic'?baseNames.find(n=>` ${base} `.includes(` ${n} `)):undefined;
 if(name===undefined)return undefined;
 const index=table.bases[name]!;
 let found=classes.get(index);
 if(!found){
  const tiers=new Map<number,{tier?:number;tiers?:number}>(),used=new Set<number>();
  for(const s of table.classes[index]!)table.series[s]!.forEach((mod,at,list)=>{tiers.set(mod,untiered.has(s)?{}:{tier:at+1,tiers:list.length});used.add(tableOf(mod));});
  // Mods that never spawn (crafting currency, essences) can still be on the item: they count as matches, with no tier.
  const free=table.mods.flatMap((_,mod)=>!inSeries.has(mod)&&used.has(tableOf(mod))?[mod]:[]);
  found={tiers,pool:[...tiers.keys(),...free],tables:used,scaled:catalyst.has(index)};classes.set(index,found);
 }
 return found;
}

const ordinary=['explicitMods','fracturedMods','craftedMods','desecratedMods'];
const cleanStat=(s:string)=>s.replace(/\[([^\]|]+)\|([^\]]+)\]/g,'$2').replace(/\[([^\]]+)\]/g,'$1');
const NUMBER=/\((-?\d+(?:\.\d+)?)-(-?\d+(?:\.\d+)?)\)|(\d+(?:\.\d+)?)/g;
/** Wording without numbers: "Adds (10-15) to (18-26) Physical Damage" and "Adds 10 to 22 Physical Damage" both become "adds # to # physical damage". */
const shape=(line:string)=>line.replace(NUMBER,'#').toLowerCase();
const slots=(line:string)=>[...line.matchAll(NUMBER)].map(m=>m[3]!==undefined?[Number(m[3]),Number(m[3])]:[Math.abs(Number(m[1])),Math.abs(Number(m[2]))].sort((a,b)=>a-b)) as [number,number][];
/** The shown value fits the summed ranges of every mod adding to it; `raise` is how far catalyst quality may lift it. */
function fits(text:string,lines:string[],raise:number){
 const shown=slots(text),ranges=lines.map(slots);
 return ranges.every(r=>r.length===shown.length)&&shown.every(([low,high],i)=>{
  const min=ranges.reduce((sum,r)=>sum+r[i]![0],0),max=ranges.reduce((sum,r)=>sum+r[i]![1],0)*(1+raise)+(raise?0.5:0);
  return low>=min-0.01&&high<=max+0.01;
 });
}

interface Line {text:string;kind:string;shape:string}
interface Source {id:string;kinds:string[]}
const sectionOf:Record<string,string>={explicit:'explicitMods',fractured:'fracturedMods',crafted:'craftedMods',desecrated:'desecratedMods'};
/** Mod IDs the item carries: poe.ninja per section, Mobalytics prefix/suffix slugs, or PoB's own "Prefix:/Suffix:" lines for items crafted in PoB. */
function sources(item:Item):Source[]{
 const found:Source[]=[];
 for(const m of item.sourceModifiers||[]){
  if(Object.hasOwn(sectionOf,m.kind))found.push({id:m.id,kinds:[sectionOf[m.kind]!]});
  else if(m.kind==='prefix'||m.kind==='suffix')found.push({id:m.id,kinds:ordinary});
 }
 for(const m of (item.sourceText||'').matchAll(/^(?:Prefix|Suffix): (?:\{range:[\d.]+\})?(\S+)\s*$/gm))if(m[1]!=='None')found.push({id:m[1]!,kinds:ordinary});
 return found;
}

function fromIds(lines:Line[],cls:BaseClass|undefined,ids:Source[],raise:number):AffixRow[]{
 // Magnitude mods scale other rolls; with them, the ID alone says which mod it is.
 const unchecked=lines.some(l=>/modifier magnitudes/i.test(l.text));
 const parts=lines.map(()=>[] as {mod:number;row:AffixRow}[]);
 for(const source of ids){
  const mod=byId.get(source.id);
  // A jewel mod named on an amulet can't be there: the ID doesn't fit this base.
  if(mod===undefined||cls&&!cls.tables.has(tableOf(mod)))continue;
  const [id,type,affix,templates]=table.mods[mod]!,kind=source.kinds.length===1?source.kinds[0]!.replace(/Mods$/,''):'item';
  const matched:number[]=[];
  for(const template of templates){
   let fit=lines.flatMap((l,i)=>source.kinds.includes(l.kind)&&!matched.includes(i)&&l.shape===shape(template)?[i]:[]);
   // Two lines with the same wording: the value decides, or it stays open which one it is.
   if(fit.length>1)fit=fit.filter(i=>fits(lines[i]!.text,[template],raise));
   if(fit.length===1)matched.push(fit[0]!);
  }
  matched.sort((a,b)=>a-b).forEach((i,n)=>{
   const hybrid=matched.length<2?undefined:n===0?'start':n===matched.length-1?'end':'middle';
   parts[i]!.push({mod,row:{text:lines[i]!.text,type,id,instanceId:`${kind}:${id}`,...(affix?{name:affix}:{}),...cls?.tiers.get(mod),...(hybrid?{hybrid}:{})}});
  });
 }
 return lines.flatMap((l,i)=>{
  const list=parts[i]!;if(!list.length)return [];
  // A value outside the mod's range comes from another patch: the type still holds, the tier doesn't.
  const contributors=unchecked||fits(l.text,list.map(p=>templateFor(p.mod,l.shape)),raise)?list.map(p=>p.row):list.map(p=>{const {tier:_t,tiers:_n,...row}=p.row;return row;});
  return [{...contributors[0]!,kind:l.kind,...(contributors.length>1?{contributors}:{})}];
 });
}
const templateFor=(mod:number,lineShape:string)=>table.mods[mod]![3].find(t=>shape(t)===lineShape)!;

/** Text only: a line gets a mod when exactly one mod of this base fits its wording and value, all its lines included. */
function fromText(lines:Line[],cls:BaseClass,raise:number):AffixRow[]{
 if(lines.some(l=>/modifier magnitudes/i.test(l.text)))return [];
 const candidates=lines.map(()=>[] as {mod:number;at:number[]}[]);
 for(const mod of cls.pool){
  const templates=table.mods[mod]![3];
  lines.forEach((line,i)=>{
   const first=templates.findIndex(t=>shape(t)===line.shape&&fits(line.text,[t],raise));
   if(first<0)return;
   const at=templates.map((t,j)=>j===first?i:lines.findIndex((l,k)=>k!==i&&l.shape===shape(t)&&fits(l.text,[t],raise)));
   if(at.every(k=>k>=0))candidates[i]!.push({mod,at});
  });
 }
 return lines.flatMap((line,i)=>{
  const list=candidates[i]!;if(!list.length)return [];
  const only=list.length===1?list[0]!:undefined;
  if(only&&only.at.every(k=>candidates[k]!.length===1&&candidates[k]![0]!.mod===only.mod)){
   const [id,type,affix]=table.mods[only.mod]!,order=[...only.at].sort((a,b)=>a-b),n=order.indexOf(i);
   const hybrid=order.length<2?undefined:n===0?'start':n===order.length-1?'end':'middle';
   return [{text:line.text,kind:line.kind,type,id,instanceId:`text:${id}`,...(affix?{name:affix}:{}),...cls.tiers.get(only.mod),...(hybrid?{hybrid}:{})} as AffixRow];
  }
  // Several mods fit: the type is known when they all agree, the tier is not.
  const type=table.mods[list[0]!.mod]![1];
  return list.every(c=>table.mods[c.mod]![1]===type)?[{text:line.text,kind:line.kind,type,id:''}]:[];
 });
}

/** Baked rows from the hand-checked catalogue gain the tier count when the table agrees on the tier. */
function baked(rows:AffixRow[],cls:BaseClass|undefined):AffixRow[]{
 const count=(a:AffixRow):AffixRow=>{const mod=byId.get(a.id),known=mod===undefined?undefined:cls?.tiers.get(mod);return known?.tier&&known.tier===a.tier&&known.tiers?{...a,tiers:known.tiers}:a;};
 return rows.map(a=>({...count(a),...(a.contributors?{contributors:a.contributors.map(count)}:{})}));
}

const cache=new WeakMap<Item,AffixRow[]>();
/** Prefix/suffix rows with tiers, worked out each time an item is shown, so saved builds gain from newer tables. */
export function affixRows(item:Item):AffixRow[]{
 let rows=cache.get(item);if(rows)return rows;
 const sections=item.sourceSections?.length?item.sourceSections:[{kind:'explicitMods',mods:item.mods}];
 const lines=sections.filter(s=>ordinary.includes(s.kind)).flatMap(s=>s.mods.map(m=>{const text=cleanStat(m);return {text,kind:s.kind,shape:shape(text)};}));
 const cls=baseClass(item),ids=sources(item);
 // Catalysts only lift some mods on rings, amulets and belts. PoB writes the quality out; elsewhere assume the most.
 const raise=cls?.scaled?(item.quality??(item.sourceText?0:20))/100:0;
 rows=item.rarity==='unique'?[]:ids.length?fromIds(lines,cls,ids,raise):item.affixRows?.length?baked(item.affixRows,cls):cls&&['magic','rare'].includes(item.rarity||'')?fromText(lines,cls,raise):[];
 cache.set(item,rows);
 return rows;
}
